pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint64 ts, address actor) public {
        vm.assume(ts > 0);
        vm.assume(actor != address(0));
        vm.warp(ts);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        bool ok;
        (bool sent, ) = address(c).call{value: 10 ether}("");
        ok = sent;
        assertTrue(ok, "first 10-ether call must succeed when block.timestamp > 0");
    }
}
